 "content": "from collections import Counter

# The noisy grids carry a signal in the frequency of colors 1, 2, or 3.
# Each signal color selects its associated 3x3 glyph.
_GLYPHS = {
    1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
    2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
    3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
}

def transform(grid):
    counts = Counter(v for row in grid for v in row)
    signal = max((1, 2, 3), key=lambda color: counts[color])
    return [row[:] for row in _GLYPHS[signal]]
